function mlFit(diameter,maxW,maxH,aspect,requested){if(![diameter,maxW,maxH,aspect].every(v=>Number.isFinite(v)&&v>0))throw Error(mlT("Please check the selected options."));const angularLimit=65*Math.PI/180,radius=diameter/2,sphereLimit=2*angularLimit*radius/Math.hypot(1,1/aspect),ceiling=Math.min(maxW,maxH*aspect,sphereLimit),minimum=Math.min(8,ceiling),suggested=Math.min(diameter*.28,ceiling*.9),width=Math.max(minimum,Math.min(ceiling,Number.isFinite(requested)?requested:suggested));return {width,height:width/aspect,ceiling,minimum,cornerAngle:Math.hypot(width,width/aspect)/diameter};}
