function mlBasis(latitude=.3,longitude=0){if(![latitude,longitude].every(Number.isFinite))throw Error(mlT("Please check the selected options."));const cy=Math.cos(latitude),sy=Math.sin(latitude),cx=Math.cos(longitude),sx=Math.sin(longitude);return {east:[cx,0,-sx],north:[-sy*sx,cy,-sy*cx],origin:[cy*sx,sy,cy*cx]};}
