// Both opposite rings share the user's blue ellipse proportions.
// The sphere and the two main great circles stay unchanged.
// In front-axis projection: x^2/a^2 + y^2/(a*s)^2 = 1.
const ML_CLASSIC=Object.freeze({axisAngle:.82,curveOffset:.50,halfWidth:.038,feather:.006,ellipseScale:.83383796});
const ML_CLASSIC_AXIS=Object.freeze([Math.cos(ML_CLASSIC.axisAngle),0,-Math.sin(ML_CLASSIC.axisAngle)]);
