  const wa=warp(a),wb=warp(b);let error=0;
  for(const t of [.25,.5,.75]){const p=warp(mid(a,b,t)),chord=mid(wa,wb,t);error=Math.max(error,Math.hypot(p[0]-chord[0],p[1]-chord[1]));}
  if(depth<14&&error>.35){const m=mid(a,b,.5);segment(a,m,points,depth+1);segment(m,b,points,depth+1);}
  else{points.push(wa);minY=Math.min(minY,wa[1]);maxY=Math.max(maxY,wa[1]);}
